	dlansp.ndarray( 'row-major', 'M', void 0, 2, AP, 1, 0 ); // $ExpectError
	dlansp.ndarray( 'row-major', 'M', [], 2, AP, 1, 0 ); // $ExpectError
	dlansp.ndarray( 'row-major', 'M', {}, 2, AP, 1, 0 ); // $ExpectError
