// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const AP = new Float64Array( [ 1.0, 2.0, 5.0 ] );

	dlansp.ndarray(); // $ExpectError
	dlansp.ndarray( 'row-major' ); // $ExpectError
	dlansp.ndarray( 'row-major', 'M' ); // $ExpectError
	dlansp.ndarray( 'row-major', 'M', 'upper' ); // $ExpectError
	dlansp.ndarray( 'row-major', 'M', 'upper', 2 ); // $ExpectError
	dlansp.ndarray( 'row-major', 'M', 'upper', 2, AP ); // $ExpectError
	dlansp.ndarray( 'row-major', 'M', 'upper', 2, AP, 1 ); // $ExpectError
	dlansp.ndarray( 'row-major', 'M', 'upper', 2, AP, 1, 0, 10 ); // $ExpectError
}
